if ($show_source != true) {
if (read_config_option('storage_location')) {
if (rrdtool_execute("file_exists $data_source_path", true, RRDTOOL_OUTPUT_BOOLEAN, $rrdtool_pipe, 'POLLER')) {
return -1;
}
} elseif (file_exists($data_source_path)) {
return -1;
}
