if ($rc === false) {
$check['err_msg'] = __('ERROR while writing XML file: %s', $xml_file);
return $check;
} else {

if (is_writable($file)) {

rrdtool_execute("restore -f $xml_file $file", false, RRDTOOL_OUTPUT_STDOUT, $rrdtool_pipe, 'UTIL');

