$insert = $dom->getElementsByTagName('rra')->item(0);


$new_node = $dom->importNode($new_node, true);

$insert->parentNode->insertBefore($new_node, $insert);
}

/** append a <DS> subtree to the <CDP_PREP> subtrees of a RRD XML structure
