}
break;
}
}

$graph_opts .= "$rigid" . trim("$scale$unit_value$unit_exponent_value$graph_legend", "\n\r " . RRD_NL) . RRD_NL;


$graph_opts .= rrdtool_function_format_graph_date($graph_data_array);


