import csv
from io import StringIO

def iter_csv(data):
""" Stream CSV file to user for download """
line = StringIO()
writer = csv.writer(line)
writer.writerow([col_1, col_2])
for csv_line in data:
writer.writerow([
str(csv_line[0][:-4]).replace('T', ' '),
csv_line[1]
])
line.seek(0)
yield line.read()
line.truncate(0)
line.seek(0)

