knowledge_service_handler.create_knowledge_space(
KnowledgeSpaceRequest(
name=space_name,
desc="first db-gpt rag application",
owner="dbgpt",
)
)
return Result.succ(
knowledge_service_handler.create_knowledge_document(
space=space_name, request=request
