(
(output_type in ['sec', 'pwm'] and float(amount) >= 0) or
output_type == 'vol' or
output_type == 'value'
)):
out_status = daemon.output_on_off(
output_id,
state,
output_type=output_type,
amount=float(amount),
output_channel=output_channel)
